from functools import lru_cache

def word_break(s: str, word_dict: list[str]) -> list[str]:
    """Return every sentence that segments s into words from word_dict."""
    if not s:
        return []

    words = set(word_dict)
    words.discard("")  # Empty words cannot make progress.
    if not words:
        return []

    n = len(s)
    max_word_len = max(map(len, words))

    # Mark suffixes that can be segmented, so the search skips dead ends.
    can_break = [False] * (n + 1)
    can_break[n] = True
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, min(n, i + max_word_len) + 1):
            if can_break[j] and s[i:j] in words:
                can_break[i] = True
                break

    if not can_break[0]:
        return []

    @lru_cache(None)
    def build(i: int) -> tuple[str, ...]:
        if i == n:
            return ("",)

        sentences = []
        for j in range(i + 1, min(n, i + max_word_len) + 1):
            word = s[i:j]
            if word in words and can_break[j]:
                for suffix in build(j):
                    sentences.append(word if not suffix else word + " " + suffix)
        return tuple(sentences)

    return list(build(0))
```

