def is_match(s: str, p: str) -> bool:
    """Return whether p fully matches s; '.' matches one character and '*' repeats."""
    m = len(p)

    # Reject malformed patterns: '*' must follow exactly one non-'*' atom.
    for i, ch in enumerate(p):
        if ch == "*" and (i == 0 or p[i - 1] == "*"):
            return False

    # dp[j]: whether the processed prefix of s matches p[:j].
    dp = [False] * (m + 1)
    dp[0] = True

    # Empty string can match repetitions such as a*, a*b*, etc.
    for j in range(2, m + 1):
        if p[j - 1] == "*":
            dp[j] = dp[j - 2]

    for char in s:
        diagonal = dp[0]  # Previous row's dp[j - 1].
        dp[0] = False

        for j in range(1, m + 1):
            old = dp[j]  # Previous row's dp[j].
            token = p[j - 1]

            if token == "*":
                atom = p[j - 2]
                # Use zero copies, or consume this character and keep repeating.
                dp[j] = dp[j - 2] or (
                    (atom == "." or atom == char) and old
                )
            else:
                dp[j] = diagonal and (token == "." or token == char)

            diagonal = old

    return dp[m]
```

The DP recurrence handles `*` as either zero copies of its preceding atom or one more matching character. The in-place update uses **O(len(p)) space** and **O(len(s) × len(p)) time**.

