def word_break(s: str, word_dict: list[str]) -> list[str]:
    if not s:
        return []

    # Trie lets us find matching words without creating substrings.
    root = {}
    for word in set(word_dict):
        if not word:
            continue
        node = root
        for char in word:
            node = node.setdefault(char, {})
        node[None] = word  # terminal marker

    @lru_cache(maxsize=None)
    def build(start: int) -> tuple[str, ...]:
        if start == len(s):
            return ("",)

        sentences = []
        node = root

        for end in range(start, len(s)):
            node = node.get(s[end])
            if node is None:
                break

            word = node.get(None)
            if word is not None:
                for suffix in build(end + 1):
                    sentences.append(
                        word if not suffix else f"{word} {suffix}"
                    )

        return tuple(sentences)

    return list(build(0))
```

Memoization avoids recomputing segmentations from the same position, and the trie avoids testing substrings that cannot be dictionary words. The number of results can be exponential, so runtime and memory necessarily depend on the total output size.

