    """Count the ways to form t as a subsequence of s."""
    dp = [0] * (len(t) + 1)
    dp[0] = 1  # The empty string is a subsequence in one way.

    for ch in s:
        for j in range(len(t) - 1, -1, -1):
            if ch == t[j]:
                dp[j + 1] += dp[j]

    return dp[len(t)]
